moves={'1':(5,-5),'4':(0,0),'5':(3,-13),'7':(-4,-3),'8':(-9,1)}
# Associate each source nonzero cell to the movable component color; associate each 2 marker explicitly.
markers={
'1':[(2,12),(4,12),(4,17),(6,15)],
'4':[(9,12),(11,10),(12,10),(13,12)],
'5':[(9,20),(12,20)],
'7':[(16,10),(16,13),(17,15),(19,10)],
'8':[(16,6),(18,6)]
}
name_for_val={int(k):k for k in moves}
assigned2={p:k for k,ps in markers.items() for p in ps}
assert len(assigned2)==16
out=[[0]*22 for _ in range(22)]
collisions=[]
for r,row in enumerate(rows):
 for c,v in enumerate(row):
  if not v: continue
  k=assigned2[(r,c)] if v==2 else name_for_val[v]
  dr,dc=moves[k]; nr,nc=r+dr,c+dc
  if not (0<=nr<22 and 0<=nc<22): print('out of range',v,(r,c),(nr,nc))
  if out[nr][nc] not in (0,v): collisions.append(((nr,nc),out[nr][nc],v,k))
  if out[nr][nc]==2 and v==2: pass
  elif out[nr][nc] not in (0,v): pass
  else: out[nr][nc]=v
print('collisions',collisions)
for row in out: print(' '.join(map(str,row)))
